type Pagamento =
  | { tipo: 'pix'; chave: string }
  | { tipo: 'boleto'; linha: string }
  | { tipo: 'cartao'; final: string };

function descrever(p: Pagamento): string {
  switch (p.tipo) {
    case 'pix':
      return 'Pix ' + p.chave;
    case 'boleto':
      return 'Boleto ' + p.linha;
    default: {
      const nunca: never = p;
      return nunca;
    }
  }
}

