class Dinheiro {
  readonly centavos: number;
  readonly moeda: string;
  constructor(centavos: number, moeda: string) {
    this.centavos = centavos;
    this.moeda = moeda;
  }
  igual(o: Dinheiro) {
    return this.centavos === o.centavos && this.moeda === o.moeda;
  }
  somar(o: Dinheiro) {
    return new Dinheiro(this.centavos + o.centavos, this.moeda);
  }
}

const a = new Dinheiro(1000, 'BRL');
const b = new Dinheiro(1000, 'BRL');
