class Pedido {
  #itens: { produto: string; qtd: number }[] = [];
  fechado = false;
  adicionar(produto: string, qtd: number) {
    if (this.fechado) throw new Error('pedido fechado');
    this.#itens.push({ produto, qtd });
  }
  fechar() {
    if (this.#itens.length === 0) throw new Error('pedido sem itens');
    this.fechado = true;
  }
  get quantidade() {
    return this.#itens.reduce((s, i) => s + i.qtd, 0);
  }
}

