type Evento =
  | { tipo: 'depositou'; valor: number }
  | { tipo: 'sacou'; valor: number }
  | { tipo: 'bloqueou' };
type Conta = { saldo: number; bloqueada: boolean };

const aplicar = (c: Conta, e: Evento): Conta => {
  switch (e.tipo) {
    case 'depositou': return { ...c, saldo: c.saldo + e.valor };
    case 'sacou': return { ...c, saldo: c.saldo - e.valor };
    case 'bloqueou': return { ...c, bloqueada: true };
  }
};

