const pedidos: string[] = [];
const outbox: { evento: string; enviado: boolean }[] = [];
const broker: string[] = [];

function criarPedido(id: string, falhar = false) {
  const marca = [pedidos.length, outbox.length] as const;
  try {
    pedidos.push(id);
    outbox.push({ evento: 'pedido.criado:' + id, enviado: false });
    if (falhar) throw new Error('violou uma constraint');
  } catch {
    pedidos.length = marca[0];
    outbox.length = marca[1];
    console.log('rollback de ' + id);
  }
}

function publicarPendentes() {
  for (const linha of outbox.filter((l) => !l.enviado)) {
    broker.push(linha.evento);
    linha.enviado = true;
  }
}

criarPedido('p1');
criarPedido('p2', true);
console.log(pedidos.length, outbox.length, broker.length);
publicarPendentes();
publicarPendentes();
console.log(broker);

let idas = 0;
