let agora = 0;
let idas = 0;
let precoNoBanco = 10;
const cache = new Map<string, { valor: number; expira: number }>();

function preco(id: string) {
  const guardado = cache.get(id);
  if (guardado && guardado.expira > agora) return guardado.valor;
  idas++;
  cache.set(id, { valor: precoNoBanco, expira: agora + 60 });
  return precoNoBanco;
}

